//! Titan VM — Stack-based virtual machine.\n\nuse titan_codegen::{CompiledModule, Op};\n\n#[derive(Debug, Clone, PartialEq)]\npub enum Value {\n    Int(i64), Float(f64), Bool(bool), Str(String), Nil,\n    Array(Vec<Value>), Function(usize),\n}\n\npub fn val_to_string(val: &Value) -> String {\n    match val {\n        Value::Int(i) => i.to_string(),\n        Value::Float(f) => f.to_string(),\n        Value::Bool(b) => b.to_string(),\n        Value::Str(s) => s.clone(),\n        Value::Nil => \"nil\".into(),\n        Value::Array(arr) => format!(\"[{}]\", arr.iter().map(val_to_string).collect::<Vec<_>>().join(\", \")),\n        Value::Function(i) => format!(\"<fn[{}]>\", i),\n    }\n}\n\npub struct Vm {\n    module: CompiledModule,\n    stack: Vec<Value>,\n    globals: std::collections::HashMap<String, Value>,\n}\n\nimpl Vm {\n    pub fn new(module: CompiledModule) -> Self {\n        Vm { module, stack: Vec::new(), globals: std::collections::HashMap::new() }\n    }\n\n    pub fn run(&mut self) -> Option<Value> {\n        let entry = self.module.entry;\n        if entry >= self.module.functions.len() { return None; }\n        let func = &self.module.functions[entry].clone();\n        let code = &func.code;\n        let mut ip = 0;\n        let len = code.len();\n        loop {\n            if ip >= len { break; }\n            match &code[ip] {\n                Op::PushInt(v) => self.push(Value::Int(*v)),\n                Op::PushFloat(v) => self.push(Value::Float(*v)),\n                Op::PushBool(v) => self.push(Value::Bool(*v)),\n                Op::PushNil => self.push(Value::Nil),\n                Op::PushStr(idx) => {\n                    let s = self.module.string_table.get(*idx).cloned().unwrap_or_default();\n                    self.push(Value::Str(s));\n                }\n                Op::PushLocal(offset) => {\n                    let val = self.stack.get(*offset).cloned().unwrap_or(Value::Nil);\n                    self.push(val);\n                }\n                Op::PushGlobal(idx) => {\n                    let name = self.module.global_names.get(*idx).cloned().unwrap_or_default();\n                    let val = self.globals.get(&name).cloned().unwrap_or(Value::Nil);\n                    self.push(val);\n                }\n                Op::StoreLocal(offset) => {\n                    let val = self.pop_();\n                    while self.stack.len() <= *offset { self.push(Value::Nil); }\n                    self.stack[*offset] = val;\n                }\n                Op::StoreGlobal(idx) => {\n                    let val = self.pop_();\n                    let name = self.module.global_names.get(*idx).cloned().unwrap_or_default();\n                    self.globals.insert(name, val);\n                }\n                Op::Add => self.binop(|a, b| match (a, b) {\n                    (Value::Int(ai), Value::Int(bi)) => Value::Int(ai + bi),\n                    (Value::Float(af), Value::Float(bf)) => Value::Float(af + bf),\n                    (Value::Str(sa), Value::Str(sb)) => Value::Str(format!(\"{}{}\", sa, sb)),\n                    _ => Value::Nil,\n                }),\n                Op::Sub => self.binop(|a, b| match (a, b) {\n                    (Value::Int(ai), Value::Int(bi)) => Value::Int(ai - bi),\n                    (Value::Float(af), Value::Float(bf)) => Value::Float(af - bf),\n                    _ => Value::Nil,\n                }),\n                Op::Mul => self.binop(|a, b| match (a, b) {\n                    (Value::Int(ai), Value::Int(bi)) => Value::Int(ai * bi),\n                    (Value::Float(af), Value::Float(bf)) => Value::Float(af * bf),\n                    _ => Value::Nil,\n                }),\n                Op::Div => self.binop(|a, b| match (a, b) {\n                    (Value::Int(ai), Value::Int(bi)) if bi != 0 => Value::Int(ai / bi),\n                    (Value::Float(af), Value::Float(bf)) if bf != 0.0 => Value::Float(af / bf),\n                    _ => Value::Nil,\n                }),\n                Op::Neg => {\n                    let val = self.pop_();\n                    match val {\n                        Value::Int(i) => self.push(Value::Int(-i)),\n                        Value::Float(f) => self.push(Value::Float(-f)),\n                        _ => self.push(Value::Nil),\n                    }\n                }\n                Op::Eq => self.binop(|a, b| Value::Bool(a == b)),\n                Op::Neq => self.binop(|a, b| Value::Bool(a != b)),\n                Op::Lt => self.binop(|a, b| match (a, b) {\n                    (Value::Int(ai), Value::Int(bi)) => Value::Bool(ai < bi),\n                    (Value::Float(af), Value::Float(bf)) => Value::Bool(af < bf),\n                    _ => Value::Bool(false),\n                }),\n                Op::Gt => self.binop(|a, b| match (a, b) {\n                    (Value::Int(ai), Value::Int(bi)) => Value::Bool(ai > bi),\n                    (Value::Float(af), Value::Float(bf)) => Value::Bool(af > bf),\n                    _ => Value::Bool(false),\n                }),\n                Op::Print => {\n                    let val = self.pop_();\n                    println!(\"{}\", val_to_string(&val));\n                }\n                Op::Call(_arg_count) => {\n                    // Pop args and call function — simplified for now\n                    // Full impl would push new frame\n                    self.push(Value::Int(0));\n                }\n                Op::Ret => return self.stack.pop(),\n                Op::RetVoid => return Some(Value::Nil),\n                Op::Jump(target) => { ip = *target; continue; }\n                Op::JumpIfFalse(target) => {\n                    let cond = self.pop_();\n                    match cond {\n                        Value::Bool(false) | Value::Nil => { ip = *target; continue; }\n                        _ => {}\n                    }\n                }\n                Op::Loop(target) => { ip = *target; continue; }\n                Op::Pop => { self.pop_(); }\n                Op::NewArray(count) => {\n                    let mut arr = Vec::with_capacity(*count);\n                    for _ in 0..*count {\n                        arr.insert(0, self.pop_());\n                    }\n                    self.push(Value::Array(arr));\n                }\n                Op::NewTuple(count) => {\n                    let mut tup = Vec::with_capacity(*count);\n                    for _ in 0..*count {\n                        tup.insert(0, self.pop_());\n                    }\n                    // Tuples are stored as arrays for now\n                    self.push(Value::Array(tup));\n                }\n                Op::Halt => return Some(Value::Nil),\n                _ => {}\n            }\n            ip += 1;\n        }\n        Some(Value::Nil)\n    }\n\n    fn push(&mut self, v: Value) { self.stack.push(v); }\n    fn pop_(&mut self) -> Value { self.stack.pop().unwrap_or(Value::Nil) }\n    fn binop<F: FnOnce(Value, Value) -> Value>(&mut self, f: F) {\n        let b = self.pop_();\n        let a = self.pop_();\n        self.push(f(a, b));\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use titan_codegen::AstCompiler;\n    use titan_lexer::Lexer;\n    use titan_parser::Parser;\n\n    fn run_source(src: &str) -> Option<Value> {\n        let mut lex = Lexer::new(src);\n        let (tokens, _) = lex.tokenize();\n        let mut p = Parser::new(tokens.to_vec());\n        let prog = p.parse_program().unwrap();\n        let mut compiler = AstCompiler::new();\n        let module = compiler.compile_program(&prog).unwrap();\n        let mut vm = Vm::new(module);\n        vm.run()\n    }\n\n    #[test]\n    fn test_vm_basic() {\n        let r = run_source(\"fn main() { let x = 40 + 2 }\");\n        assert!(r.is_some());\n    }\n\n    #[test]\n    fn test_vm_arithmetic() {\n        // 40 + 2 = 42\n        let r = run_source(\"fn main() { 40 + 2 }\");\n        assert_eq!(r, Some(Value::Int(42)));\n    }\n\n    #[test]\n    fn test_vm_comparison() {\n        let r = run_source(\"fn main() { 5 == 5 }\");\n        assert_eq!(r, Some(Value::Bool(true)));\n    }\n\n    #[test]\n    fn test_vm_print() {\n        let r = run_source(\"fn main() { print(42) }\");\n        assert_eq!(r, Some(Value::Nil));\n    }\n}"}